//! csv_encoder — Rust native plugin implementing pipeline.encoder v1.0.
//!
//! This is a hand-written cdylib plugin (not generated by polyplugc).
//! It implements the "pipeline.encoder" contract: encode(record: DataRecord) -> Buffer.

// ─── ABI Types (mirrored from polyplug) ──────────────────────────────────────
// We cannot depend on polyplug here (cdylib circular dependency).
// Mirror the ABI types inline. These are frozen per §7 ABI Stability.

use std::sync::OnceLock;

/// Non-owning UTF-8 string view — mirrors polyplug::abi::StringView.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct StringView {
    pub ptr: *const u8,
    pub len: usize,
}

impl StringView {
    /// Construct the null/empty StringView.
    pub const fn null() -> StringView {
        StringView {
            ptr: core::ptr::null(),
            len: 0,
        }
    }
}

// SAFETY: StringView is a read-only view into externally-owned 'static data.
// Concurrent reads from multiple threads are safe.
unsafe impl Send for StringView {}
// SAFETY: Same reasoning as Send.
unsafe impl Sync for StringView {}

/// ABI error — mirrors polyplug::abi::AbiError.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct AbiError {
    pub code: u32,
    pub message: StringView,
}

impl AbiError {
    /// Construct a success AbiError.
    pub const fn ok() -> AbiError {
        AbiError {
            code: 0,
            message: StringView::null(),
        }
    }
}

// SAFETY: AbiError is a plain-old-data struct with no interior mutability.
unsafe impl Send for AbiError {}
// SAFETY: AbiError is a plain-old-data struct with no interior mutability.
unsafe impl Sync for AbiError {}

/// Plugin VTable — mirrors polyplug::abi::PluginVTable.
#[repr(C)]
pub struct PluginVTable {
    pub contract_id: u64,
    pub contract_version: u32,
    pub function_count: u32,
    pub functions: *const FnPtr,
}

// SAFETY: PluginVTable points to 'static function arrays. All fields are static pointers.
unsafe impl Send for PluginVTable {}
// SAFETY: PluginVTable points to 'static function arrays. All fields are static pointers.
unsafe impl Sync for PluginVTable {}

/// Plugin descriptor — mirrors polyplug::abi::PluginDescriptor.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct PluginDescriptor {
    pub name: StringView,
    pub contract_name: StringView,
    pub version_major: u32,
    pub version_minor: u32,
    pub version_patch: u32,
}

// SAFETY: PluginDescriptor contains only StringViews and u32 values.
unsafe impl Send for PluginDescriptor {}
// SAFETY: PluginDescriptor contains only StringViews and u32 values.
unsafe impl Sync for PluginDescriptor {}

/// Opaque handle to a loaded plugin — mirrors polyplug::abi::PluginHandle.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PluginHandle {
    pub index: u32,
    pub generation: u32,
}

/// Host VTable — mirrors polyplug::abi::HostVTable.
#[repr(C)]
pub struct HostVTable {
    pub alloc: unsafe extern "C" fn(size: usize, align: usize) -> *mut u8,
    pub free: unsafe extern "C" fn(ptr: *mut u8, size: usize, align: usize),
    pub find_by_contract: unsafe extern "C" fn(contract_id: u64, min_version: u32) -> PluginHandle,
    pub find_by_bundle:
        unsafe extern "C" fn(bundle_id: u64, contract_id: u64, min_version: u32) -> PluginHandle,
    pub find_all_by_contract: unsafe extern "C" fn(
        contract_id: u64,
        min_version: u32,
        out: *mut PluginHandle,
        out_cap: usize,
    ) -> usize,
    pub resolve_plugin: unsafe extern "C" fn(handle: PluginHandle) -> *const PluginVTable,
    pub get_extension: unsafe extern "C" fn(extension_id: u32) -> *const (),
}

/// Plugin registrar — mirrors polyplug::abi::PluginRegistrar.
#[repr(C)]
pub struct PluginRegistrar {
    pub register_plugin: unsafe extern "C" fn(
        registrar: *mut PluginRegistrar,
        descriptor: *const PluginDescriptor,
        vtable: *const PluginVTable,
    ) -> AbiError,
    pub host: *const HostVTable,
}

// ─── Function pointer newtype wrapper ────────────────────────────────────────
// Raw `*const ()` is not `Sync`, but function pointers in a static array are
// effectively 'static and immutable. We wrap them to implement Sync.

/// Wrapper for a function pointer stored in a static vtable array.
/// The pointer is 'static (lifetime of the plugin binary) and read-only.
#[repr(transparent)]
pub struct FnPtr(pub *const ());

// SAFETY: FnPtr wraps a 'static function pointer. Function pointers are safe
// to share across threads — the function itself handles its own synchronization.
unsafe impl Send for FnPtr {}
// SAFETY: Function pointers are inherently Sync — multiple threads may call the
// same function concurrently. The underlying data is read-only 'static memory.
unsafe impl Sync for FnPtr {}

// ─── Trace Extension (mirrored layout) ───────────────────────────────────────
// EXT_TRACE_ID = FNV-1a 32-bit hash of b"trace" = 0xC4EB9AEE
// TraceVTable layout from crates/polyplug/src/extensions/trace/mod.rs

/// FNV-1a 32-bit hash of b"trace" — matches EXT_TRACE_ID in host trace extension.
const EXT_TRACE_ID: u32 = 0xC4EB9AEE_u32;

/// C-ABI vtable for the trace extension — mirrors polyplug::extensions::trace::TraceVTable.
#[repr(C)]
pub struct TraceVTable {
    /// Emit a trace message. msg is valid UTF-8 for call duration.
    pub emit: unsafe extern "C" fn(msg: StringView, state: *const ()),
    /// Opaque pointer to the heap-allocated TraceState (same as this vtable's state field).
    pub state: *const (),
}

// SAFETY: TraceVTable fields are a function pointer and a *const () to a leaked allocation.
// Function pointers are thread-safe. The state pointer is immutable after construction.
unsafe impl Send for TraceVTable {}
// SAFETY: Same reasoning — no mutable state, concurrent reads are safe.
unsafe impl Sync for TraceVTable {}

// ─── Contract ID ──────────────────────────────────────────────────────────────
// FNV1a-64 of "pipeline.encoder" at major version 1.
// Computed by: contract_id("pipeline.encoder", 1) = 0x12AD37F43386F752

const ENCODER_CONTRACT_ID: u64 = 0x12AD37F43386F752;

// ─── pipeline.encoder contract types ─────────────────────────────────────────

/// Input record to be encoded into a CSV line.
#[repr(C)]
pub struct DataRecord {
    pub name: StringView,
    pub value: StringView,
    pub count: u32,
}

/// Output byte buffer produced by encoding one DataRecord.
#[repr(C)]
pub struct Buffer {
    pub ptr: *const u8,
    pub len: usize,
    pub cap: usize,
}

// ─── Trace callback storage ─────────────────────────────────────────────────

/// Newtype wrapping `*const TraceVTable` so we can store it in a `static OnceLock`.
/// The pointer is a stable leaked allocation from the host runtime.
#[derive(Clone, Copy)]
struct TracePtr(*const TraceVTable);

// SAFETY: TracePtr wraps a pointer to a leaked host allocation that is
// immutable after construction. Reading it from multiple threads is safe.
unsafe impl Send for TracePtr {}
// SAFETY: Same reasoning — no mutable state, concurrent reads are safe.
unsafe impl Sync for TracePtr {}

/// Stores the TraceVTable pointer acquired at init time. None = no trace extension present.
static TRACE_CB: OnceLock<Option<TracePtr>> = OnceLock::new();

/// Emit a trace message if the trace extension is available.
///
/// # Safety
/// This function reads the TRACE_CB OnceLock which stores a potentially-null pointer.
/// The pointer is valid for the lifetime of the runtime (host guarantees this).
unsafe fn emit_trace(msg: &str) {
    if let Some(Some(TracePtr(vtable_ptr))) = TRACE_CB.get() {
        // SAFETY: vtable_ptr was obtained from get_extension(EXT_TRACE_ID) and is
        // guaranteed non-null here. It points to a valid TraceVTable for the lifetime
        // of the host runtime. msg is a valid UTF-8 &str for this call's duration.
        let sv = StringView {
            ptr: msg.as_ptr(),
            len: msg.len(),
        };
        unsafe { ((**vtable_ptr).emit)(sv, (**vtable_ptr).state) };
    }
}

// ─── Implementation ───────────────────────────────────────────────────────────

/// The `encode` function: serializes a DataRecord into a CSV line (Buffer).
///
/// Signature matches the generic dispatch: `extern "C" fn(*const (), *mut ()) -> AbiError`.
///
/// # Safety
/// `args` must point to a valid `DataRecord`. `out` must point to a valid `Buffer`.
extern "C" fn plugin_encode(args: *const (), out: *mut ()) -> AbiError {
    // SAFETY: The host runtime guarantees args points to a valid DataRecord
    // and out points to a valid Buffer. Enforced by the ABI contract.
    unsafe { encode_impl(args as *const DataRecord, out as *mut Buffer) }
}

/// Core encode implementation operating on typed pointers.
///
/// # Safety
/// `input` must be a non-null pointer to a valid `DataRecord`.
/// `out` must be a non-null pointer to a valid `Buffer` writable by caller.
unsafe fn encode_impl(input: *const DataRecord, out: *mut Buffer) -> AbiError {
    // SAFETY: input is non-null and valid per ABI contract from plugin_encode.
    let record: &DataRecord = unsafe { &*input };

    // SAFETY: record.name.ptr points to valid UTF-8 bytes for record.name.len bytes — guaranteed by host.
    let name_bytes: &[u8] = if record.name.ptr.is_null() {
        b""
    } else {
        unsafe { core::slice::from_raw_parts(record.name.ptr, record.name.len) }
    };

    // SAFETY: record.value.ptr points to valid UTF-8 bytes for record.value.len bytes — guaranteed by host.
    let value_bytes: &[u8] = if record.value.ptr.is_null() {
        b""
    } else {
        unsafe { core::slice::from_raw_parts(record.value.ptr, record.value.len) }
    };

    let name_str: &str = match core::str::from_utf8(name_bytes) {
        Ok(s) => s,
        Err(_) => {
            return AbiError {
                code: 1,
                message: StringView {
                    ptr: b"invalid UTF-8 in name".as_ptr(),
                    len: 21,
                },
            };
        }
    };

    let value_str: &str = match core::str::from_utf8(value_bytes) {
        Ok(s) => s,
        Err(_) => {
            return AbiError {
                code: 1,
                message: StringView {
                    ptr: b"invalid UTF-8 in value".as_ptr(),
                    len: 22,
                },
            };
        }
    };

    // Format as CSV: "name,value,count\n"
    let csv_line: String = format!("{},{},{}\n", name_str, value_str, record.count);

    // Leak the CSV line bytes into 'static memory.
    // This is acceptable in the examples context — the host is expected to
    // manage the lifetime of output Buffer data externally.
    let csv_bytes: Vec<u8> = csv_line.into_bytes();
    let len: usize = csv_bytes.len();
    let cap: usize = csv_bytes.capacity();
    let leaked: &'static [u8] = Box::leak(csv_bytes.into_boxed_slice());

    let buffer = Buffer {
        ptr: leaked.as_ptr(),
        len,
        cap,
    };

    // SAFETY: out is non-null and points to a valid Buffer per ABI contract.
    unsafe {
        core::ptr::write(out, buffer);
    }

    // Emit trace if the extension is available.
    // SAFETY: emit_trace reads a stable OnceLock — no unsoundness.
    unsafe { emit_trace("[csv_encoder] encode called") };

    AbiError::ok()
}

// ─── Static VTable ────────────────────────────────────────────────────────────

// The function pointer array for the pipeline.encoder vtable.
// function_id 0 = encode(args: DataRecord) -> Buffer
static CSV_ENCODER_FNS: [FnPtr; 1] = [FnPtr(plugin_encode as *const ())];

static CSV_ENCODER_VTABLE: PluginVTable = PluginVTable {
    contract_id: ENCODER_CONTRACT_ID,
    contract_version: 0u32, // v1.0: minor=0, patch=0
    function_count: 1,
    functions: CSV_ENCODER_FNS.as_ptr(),
};

static CSV_ENCODER_DESCRIPTOR: PluginDescriptor = PluginDescriptor {
    name: StringView {
        ptr: b"csv_encoder".as_ptr(),
        len: 11,
    },
    contract_name: StringView {
        ptr: b"pipeline.encoder".as_ptr(),
        len: 16,
    },
    version_major: 1,
    version_minor: 0,
    version_patch: 0,
};

// ─── ABI Exports ─────────────────────────────────────────────────────────────

/// ABI version sentinel — loader checks this before calling polyplug_init.
#[unsafe(no_mangle)]
pub extern "C" fn polyplug_abi_version() -> u32 {
    1
}

/// Plugin init — called by the loader to register vtables.
///
/// # Safety
/// `registrar` must be a valid non-null pointer to a PluginRegistrar from the host.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn polyplug_init(registrar: *mut PluginRegistrar) -> AbiError {
    if registrar.is_null() {
        return AbiError {
            code: 1, // ABI_ERROR_GENERIC
            message: StringView::null(),
        };
    }

    // Acquire trace extension from host (nullable — missing trace ext is not an error).
    // SAFETY: registrar is non-null, so host field is valid per ABI contract.
    let host: *const HostVTable = unsafe { (*registrar).host };
    if !host.is_null() {
        // SAFETY: host is non-null and valid per ABI contract.
        let ext_ptr: *const () = unsafe { ((*host).get_extension)(EXT_TRACE_ID) };
        let trace_vtable: Option<TracePtr> = if ext_ptr.is_null() {
            None
        } else {
            Some(TracePtr(ext_ptr as *const TraceVTable))
        };
        // OnceLock::set fails silently if already initialised — acceptable at plugin load.
        let _: Result<(), _> = TRACE_CB.set(trace_vtable);
    } else {
        let _: Result<(), _> = TRACE_CB.set(None);
    }

    // Emit trace after storing the vtable pointer.
    // SAFETY: emit_trace reads a stable OnceLock — no unsoundness.
    unsafe { emit_trace("[csv_encoder] init") };

    // SAFETY: registrar is non-null and provided by the host runtime per ABI contract.
    let reg: &mut PluginRegistrar = unsafe { &mut *registrar };

    // SAFETY: register_plugin is a valid function pointer set by the host.
    // CSV_ENCODER_DESCRIPTOR and CSV_ENCODER_VTABLE are 'static.
    unsafe {
        (reg.register_plugin)(
            registrar,
            &CSV_ENCODER_DESCRIPTOR as *const PluginDescriptor,
            &CSV_ENCODER_VTABLE as *const PluginVTable,
        )
    }
}
